"""Normalize UVS dashboard JSON generated by uvcov."""
from __future__ import annotations

from pathlib import Path
from typing import Any

from ._model import dataset, json_object, metric, read_json_object


_UVS_KINDS = {"stmt": "statement", "cond": "condition", "tgl": "toggle", "fsm": "fsm_native"}


def from_uvs_json(path: str | Path, *, name: str) -> dict[str, Any]:
    """Read the uvcov dashboard JSON, preserving native metric denominators."""
    report = read_json_object(path)
    summary = json_object(report.get("summary"), "uvcov summary")
    native = json_object(summary.get("summaryData"), "uvcov summaryData")
    metrics = {}
    for key, kind in _UVS_KINDS.items():
        if key in native:
            row = json_object(native[key], f"uvcov metric {key}")
            metrics[kind] = metric(row.get("cd"), row.get("un+cd"), f"uvcov dashboard: {key}",
                                   unit="native toggle target" if key == "tgl" else None)
    if not metrics:
        raise ValueError("uvcov dashboard contains no recognized coverage metrics")
    return dataset(name, "uvs", "uvcov-dashboard", "Full scope of the supplied uvcov dashboard", metrics)
